/*
 * CoAP Client — ESP32
 * Polls a simulated CoAP server for temperature data
 * Yellow LED on D2 blinks on each successful request
 */

#include <CoapClient.h>

CoapClient client;
bool ledState = false;
int requestCount = 0;

void setup() {
  Serial.begin(115200);
  pinMode(2, OUTPUT);

  Serial.println("CoAP Client starting...");
  delay(1000);
}

void loop() {
  requestCount++;

  // GET temperature from simulated server
  CoapResponse response = client.get("sensor/temp");
  if (response.valid && response.code == COAP_CONTENT) {
    Serial.print("Temp: ");
    Serial.println(response.payload);

    // Blink LED on success
    ledState = !ledState;
    digitalWrite(2, ledState ? HIGH : LOW);
  }

  // GET humidity
  response = client.get("sensor/humidity");
  if (response.valid && response.code == COAP_CONTENT) {
    Serial.print("Humidity: ");
    Serial.println(response.payload);
  }

  // PUT update LED state
  if (requestCount % 5 == 0) {
    CoapResponse putResp = client.put("led", "{\"state\":\"on\",\"color\":\"yellow\"}");
    if (putResp.valid) {
      Serial.println("LED state updated via CoAP");
    }
  }

  Serial.print("Request #");
  Serial.println(requestCount);
  delay(2000);
}
